// game_engine.ts

function gameEngine(initialState: StateAndEvents): Promise<void> {
  let lastMove: string | null = localStorage.getItem('lastMove');
  let turn = initialGameState.currentPlayer === 'Player' ? 'X' : 'O';

  return new Promise((resolve, reject) => {
    function update(state: StateAndEvents): void {
      localStorage.setItem('state', JSON.stringify(state));
      resolve();
    }

    function gameLoop(): void {
      if (lastMove === null) {
        console.log(`${turn}'s turn`);
        const move = prompt(`${turn}, enter your move (e.g., A1B2)`).toUpperCase();
        if (move === 'QUIT') {
          localStorage.removeItem('lastMove');
          localStorage.clear(); // Clear cookies/sessionStorage/other storage
          return resolve();
        }

        try {
          const newGameState = player.makeMove(state, move);
          update(newGameState);
          lastMove = move;

          if (gameState.isGameOver()) {
            console.log(`${turn} wins!`);
            update({ status: 'Game Over' });
            localStorage.removeItem('lastMove');
            return resolve();
          }

          turn = turn === 'X' ? 'O' : 'X';
        } catch (error) {
          reject(error);
        }
      }

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  });
}

